const want = ($('list_tasks · Webhook').first().json.body || {}).state;
const norm = s => (s||'').toLowerCase();
const nodes = (($json.data||{}).viewer||{}).assignedIssues?.nodes || [];
const ids = new Set(nodes.map(n => n.id));
const projects = {};
function bucket(p){ const key = p ? p.id : '__none'; if(!projects[key]) projects[key] = { id: p?p.id:null, name: p?p.name:'Sin proyecto', tasks: [] }; return projects[key]; }
function child(c){ return { id:c.id, ref:c.identifier, title:c.title, url:c.url, priority:c.priority, state:c.state?.name, type:c.state?.type }; }
for (const n of nodes){
  if (n.parent && ids.has(n.parent.id)) continue; // shown under its parent
  let kids = (n.children?.nodes || []).map(child);
  if (want) kids = kids.filter(k => norm(k.state) === norm(want) || norm(k.type) === norm(want));
  const task = { id:n.id, ref:n.identifier, title:n.title, priority:n.priority, state:n.state?.name, type:n.state?.type, url:n.url, children: kids };
  if (want && norm(task.state) !== norm(want) && norm(task.type) !== norm(want) && !kids.length) continue;
  bucket(n.project).tasks.push(task);
}
const out = Object.values(projects).filter(p => p.tasks.length).sort((a,b)=> a.name==='Sin proyecto'?1 : b.name==='Sin proyecto'?-1 : a.name.localeCompare(b.name));
const count = out.reduce((s,p)=> s + p.tasks.length + p.tasks.reduce((x,t)=>x+t.children.length,0), 0);
return [{ json: { ok:true, count, projects: out } }];

const nodes = (($json.data||{}).projects||{}).nodes || [];
const active = nodes.filter(p => !['completed','canceled'].includes((p.state||'').toLowerCase()));
return [{ json: { ok:true, count: active.length, projects: active.map(p=>({ id:p.id, name:p.name, state:p.state, progress:p.progress, url:p.url })) } }];

const r = (($json.data||{}).issueUpdate) || {};
if (!r.success) return [{ json: { ok:false, error:'Linear update failed', raw: $json } }];
const i = r.issue || {};
return [{ json: { ok:true, result: `Task updated: ${i.title}`, id:i.id, url:i.url, state:i.state?.name } }];

const b = $('complete_task · Webhook').first().json.body || {};
const target = (b.state || 'Done');
const states = ((($json.data||{}).issue||{}).team||{}).states?.nodes || [];
const norm = s => (s||'').toLowerCase();
let st = states.find(s => norm(s.name) === norm(target));
if (!st && norm(target) === 'done') st = states.find(s => s.type === 'completed');
if (!st) return [{ json: { ok:false, error:`State '${target}' not found for this issue's team.`, available: states.map(s=>s.name) } }];
return [{ json: { id: b.id, stateId: st.id, stateName: st.name } }];

if ($json.ok === false) return [{ json: $json }];
const r = (($json.data||{}).issueUpdate) || {};
if (!r.success) return [{ json: { ok:false, error:'Linear state change failed', raw: $json } }];
const i = r.issue || {};
return [{ json: { ok:true, result: `Task moved to ${i.state?.name}: ${i.title}`, id:i.id, url:i.url, state:i.state?.name } }];
